CREATE TABLE `staff` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`campus_id` text NOT NULL REFERENCES campuses(id) ON DELETE restrict,`employee_number` text NOT NULL,`first_name` text NOT NULL,`last_name` text,`preferred_name` text,`gender` text,`date_of_birth` text,`national_id` text,`nationality` text,`religion` text,`blood_group` text,`marital_status` text,`phone` text NOT NULL,`alternate_phone` text,`email` text,`address` text,`city` text,`province` text,`emergency_contact_name` text,`emergency_contact_phone` text,`emergency_contact_relation` text,`department` text,`designation` text NOT NULL,`employment_type` text DEFAULT 'full_time' NOT NULL,`staff_category` text DEFAULT 'teaching' NOT NULL,`qualification_summary` text,`experience_years` integer DEFAULT 0 NOT NULL,`joined_on` text NOT NULL,`confirmed_on` text,`probation_ends_on` text,`left_on` text,`leaving_reason` text,`status` text DEFAULT 'active' NOT NULL,`bank_name` text,`bank_account_title` text,`bank_account_number` text,`tax_number` text,`base_salary` integer,`payroll_notes` text,`profile_notes` text,`photo_asset_id` text REFERENCES storage_assets(id) ON DELETE set null,`archived_at` integer,`archived_by` text REFERENCES users(id),`created_by` text NOT NULL REFERENCES users(id),`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `staff_org_employee_uq` ON `staff` (`organization_id`,`employee_number`);
CREATE INDEX `staff_org_status_name_idx` ON `staff` (`organization_id`,`status`,`first_name`,`last_name`);
CREATE INDEX `staff_campus_status_idx` ON `staff` (`campus_id`,`status`);
CREATE INDEX `staff_org_designation_idx` ON `staff` (`organization_id`,`designation`);
CREATE TABLE `staff_qualifications` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`degree` text NOT NULL,`institution` text,`field_of_study` text,`completed_on` text,`grade` text,`notes` text,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE INDEX `staff_qualifications_staff_idx` ON `staff_qualifications` (`organization_id`,`staff_id`);
CREATE TABLE `staff_experience` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`employer` text NOT NULL,`job_title` text NOT NULL,`started_on` text,`ended_on` text,`responsibilities` text,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE INDEX `staff_experience_staff_idx` ON `staff_experience` (`organization_id`,`staff_id`);
CREATE TABLE `staff_documents` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`asset_id` text NOT NULL REFERENCES storage_assets(id) ON DELETE restrict,`document_type` text NOT NULL,`title` text NOT NULL,`issued_on` text,`expires_on` text,`verification_status` text DEFAULT 'pending' NOT NULL,`notes` text,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE INDEX `staff_documents_staff_idx` ON `staff_documents` (`organization_id`,`staff_id`,`created_at`);
